CREATE OR REPLACE FUNCTION "${schema}".prevent_attendance_adjustment_audit_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $body$
BEGIN
    RAISE EXCEPTION 'attendance_adjustment_audit is append-only';
END;
$body$;

CREATE TRIGGER trg_attendance_adjustment_audit_append_only
BEFORE UPDATE OR DELETE ON "${schema}".attendance_adjustment_audit
FOR EACH ROW EXECUTE FUNCTION "${schema}".prevent_attendance_adjustment_audit_mutation();
